from journal.support.classification import WORKER_KINDS
from journal.support.option import USER, Option
from journal.support.option_scope import OptionScope


class WorkersOptions:
    MEMORY_WARNING_MEGABYTES = Option("workers.memory_warning_megabytes", "Memory a worker's processes may use before you are warned", "The resident memory, in megabytes, of a worker's whole process tree past which the agent that sent it is warned once", 4096, unit="MB")
    MEMORY_LIMIT_MEGABYTES = Option("workers.memory_limit_megabytes", "Memory a worker's processes may use before it is stopped", "The resident memory, in megabytes, of a worker's whole process tree past which the worker is stopped, the reason written on it", 8192, unit="MB")
    MEMORY_TOTAL_MEGABYTES = Option("workers.memory_total_megabytes", "Memory all workers' processes may use together", "The resident memory, in megabytes, of every worker's process tree added up, past which the worker using the most is stopped; 0 for no limit", 16384, unit="MB")
    TIMEOUT = Option("workers.timeout_minutes", "Time limit of a worker run", "Minutes a worker may run before it is stopped and its report states that it was; 0 sets no limit", 60, unit="min")
    REVIEWER_LIMIT = Option("workers.reviewers_most", "Reviewers: most out", "The most reviewers out at once, apart from the workers: the review queue adds a reviewer while reviews wait and fewer than this are out; they do not count toward the worker limits", 2, unit="reviewers")
    VERIFIER_LIMIT = Option("workers.verifiers_most", "Verifiers: most out", "The most verifiers out at once, apart from the workers: a verdict wanted past it waits for one to come free; they do not count toward the worker limits", 2, unit="verifiers")
    TEST_RUNS = Option("workers.test_runs", "Test runs at once", "The most queued test runs and builds going at a time across all workers; a worker's run waits for its turn", 3, unit="runs")
    TEST_WAITING = Option("workers.test_waiting", "Turns that may wait", "With the test budget, the most turns that may wait for a free run; blank is no limit", "", option_type="text", unit="turns")
    TEST_ID_LIMIT = Option("workers.tests_per_run", "Test ids in one run", "With the test budget, the most test ids one run may name", 20, unit="ids")
    TEST_RUN_MINUTES = Option("workers.test_run_minutes", "Minutes a test run may take", "With the test budget, the minutes after which a run is stopped", 10, unit="min")
    TEST_COMMAND = Option("workers.test_command", "Test command", "With the test budget or the journal running the tests, the command a turn runs with the test ids the worker lists; blank runs pytest where the project has a tests folder, and where it has none a turn is refused", "", option_type="text")
    AFFECTED_TESTS_COMMAND = Option("workers.affected_tests_command", "Command that finds the tests a change touches", "With the journal running the tests, a command handed the files a worker changed that prints the test arguments covering them, one a line; at clock-out the journal runs those the worker did not name too. Blank adds none", "", option_type="text")
    TEST_COMMAND_PROOF = Option("workers.test_command_proof", "Test command proved with", "The arguments of the passing run that proved the test command when it was set with journal tests command", "", option_type="text")
    FAILING_RUNS = Option("workers.failing_runs", "Failing runs in a row", "With the test budget, the failing runs in a row of one worker after which the agent that sent it is informed, once, until a passed run starts the count again", 3, unit="runs")
    TEST_RUN_LINES = Option("workers.test_run_lines", "Line for each failed test run", "With the test budget, the agent that sent a worker is informed in one line of each of its test runs that failed, and how many failed; off, it is informed only once a worker keeps failing", True, option_type="switch")
    WORKLOAD_WINDOW_MINUTES = Option("workers.load_window_minutes", "Load: minutes measured over", "The sliding window the arrivals, the clearings and the wait from arrival to clearing are measured over", 30, unit="min")
    WORKLOAD_SMOOTHING_MINUTES = Option("workers.load_half_life_minutes", "Load: half-life of the smoothing", "The minutes after which a measure of the load weighs half as much in the smoothed load", 10, unit="min")
    WORKLOAD_WARNING_RATIO = Option("workers.load_warn", "Load: warn at", "The load, arrivals over clearings, from which the status bar shows it as a warning", 0.7, unit="ratio")
    WORKLOAD_CRITICAL_RATIO = Option("workers.load_critical", "Load: critical at", "The load from which the status bar shows it as critical", 0.9, unit="ratio")
    PLACE_OPENING_RATIO = Option("workers.scale_up_at", "Load: add a place over", "The load that, held for the minutes below, opens one more place for a worker and a subagent, up to the ceiling", 0.8, unit="ratio")
    PLACE_CLOSING_RATIO = Option("workers.scale_down_at", "Load: remove a place under", "The load that, staying under for the minutes below, closes a place, down to the floor, never while a worker has a task or anything waits", 0.5, unit="ratio")
    PLACE_OPENING_MINUTES = Option("workers.scale_up_dwell_minutes", "Load: minutes over before a place opens", "How long the load stays over the level above before a place opens, and between two openings", 10, unit="min")
    PLACE_CLOSING_MINUTES = Option("workers.scale_down_dwell_minutes", "Load: minutes under before a place closes", "How long the load stays under the level above before a place closes, and between two closings", 20, unit="min")
    MIN_PLACES = Option("workers.place_floor", "Load: fewest worker places", "The fewest workers out at once the load may bring the limit down to; blank, the load never changes the places", "", option_type="text", unit="places", setter=USER)
    MAX_PLACES = Option("workers.place_ceiling", "Load: most worker places", "The most workers out at once the load may bring the limit up to; blank, the load never changes the places", "", option_type="text", unit="places", setter=USER)
    WEIGHT_USER_MESSAGE = Option("workers.weight_user_message", "Load: weight of a user message", "How much a message of the user's weighs in the load, a clock-out weighing 1", 3, unit="factor")
    RESEND_WEIGHT = Option("workers.weight_repeat_send_back", "Load: weight of a clock-out after a send-back", "How much a worker coming back after it was sent back weighs in the load", 1.5, unit="factor")
    WORKER_LIMIT = Option("workers.most_out", "Workers out at once", "The most workers out at a time; a dispatch past it is refused until one reports. 0 is no limit", 3, unit="workers")
    SUBAGENT_LIMIT = Option("workers.most_subagents", "Subagents running at once", "The most subagents running at a time; one more is held until one finishes. 0 is no limit", 5, unit="subagents")
    IDLE_HOURS = Option("workers.idle_hours", "Retire a resting worker after", "A worker with nothing out, nothing to check and nothing unmerged is retired after this many hours at rest, and its worktree removed, its last commit remaining; 0 never retires one", 4, unit="hours")
    MERGE_WINDOW_SECONDS = Option("workers.merge_window_seconds", "A plugin may pause a merge for", "Seconds a plugin that pauses a worker's merge, such as a judge of the whole tree, may take to answer; its own window in its manifest is cut to this, and the wait in the queue below is not counted", 180, unit="seconds")
    MERGE_LIMIT = Option("workers.merge_limit", "Merges asked about at once", "The most worker merges plugins are asked about at a time; a further merge waits until one is answered; 0 for no limit", 2, unit="merges")
    CLASH_LIMIT = Option("workers.clashes_named", "Clashes in a row before the dispatcher is informed", "How many times in a row a worker's branch is sent back to rebase because merges landed under it, after which the agent that sent it is informed so it can order the merges; 0 never informs", 3, unit="clashes")
    PROFILE_LIMIT = Option("workers.idle_kept", "Workers for reuse per profile", "The most workers of one profile out or idle for reuse; past it a dispatch of that profile is refused while one of them is idle, so the job goes to that one. Reviewers always start fresh. 0 is no limit", 8, unit="workers")
    WORKTREE_STEP = Option("workers.worktree_step", "Make worker worktrees the journal's way", "The journal makes a worker's worktree, a worktree of each inner repository it needs and its library folders; off, your own commands below make them, informed where in JOURNAL_WORKTREE and on which branch in JOURNAL_BRANCH", True, option_type="switch", scope=OptionScope.MACHINE)
    PREPARATION_COMMANDS = Option("workers.preparation_commands", "Commands before a worker's worktree is made", "Your own shell commands, one per line, run in the project folder just before a worker's worktree is made; each receives JOURNAL_WORKTREE, JOURNAL_BRANCH, JOURNAL_PROJECT, JOURNAL_REPOSITORIES, JOURNAL_LIBRARIES and JOURNAL_COPIES", [], option_type="lines", scope=OptionScope.MACHINE)
    BUILT_PATHS = Option("workers.built_paths", "Folders built from the sources", "Folders, one per line, that a build makes from the sources, such as a built viewer; a worker's merge that clashes only in them takes the project's side and builds them again with the command below", [], option_type="lines")
    COMMAND_KINDS = Option("workers.command_kinds", "Commands workers may run", "The kinds of shell command a worker may run, as the journal classifies each command, comma separated; every kind by default; journal commands always go through, and a test or a build left out is refused with the line to queue it with the journal", ", ".join(WORKER_KINDS), option_type="text", choices=WORKER_KINDS)
    BUILD_COMMAND = Option("workers.build_command", "Command that builds them", "The shell command, run in the worker's worktree, that builds the folders above again after a merge clashed only in them", "", option_type="text")
    ALLOWED_MODELS = Option("workers.allowed_models", "Models each role or agent profile may run on", "One line for each provider and role or named agent profile, such as claude reviewer: sonnet, opus; a profile with no line may run on any model of the provider, and one asking for a model outside its line is moved to the nearest listed", ["claude journal-medior: sonnet, opus", "claude journal-senior: sonnet, opus", "claude reviewer: sonnet", "claude verifier: sonnet", "codex journal-medior: gpt-5.6-sol, gpt-6.1-sol, gpt-6-astra", "codex journal-senior: gpt-5.6-sol, gpt-6.1-sol, gpt-6-astra", "codex reviewer: gpt-5.6-sol, gpt-6.1-sol", "codex verifier: gpt-5.6-sol, gpt-6.1-sol"], option_type="lines")
    COMPLETION_COMMANDS = Option("workers.completion_commands", "Commands after a worker's worktree is made", "Your own shell commands, one per line, run inside a worker's worktree once it is made, such as installing its dependencies; receiving the same values as the commands before", [], option_type="lines", scope=OptionScope.MACHINE)


